package com.csust.eyediagnosis.workflow.inference;
import com.csust.eyediagnosis.workflow.contract.*; import com.csust.eyediagnosis.workflow.domain.*; import org.junit.jupiter.api.Test; import java.util.Set; import static org.junit.jupiter.api.Assertions.*;
class ImageQualityActionTest { @Test void mapsOnlyQualityFieldsToGraphDecision() { ImageQualityAction action = new ImageQualityAction(); assertEquals(ImageQualityDecision.PASS, action.execute(new ImageQualityRouteInput(new ImageQualitySnapshot(100,false,Set.of()))).decision()); assertEquals(ImageQualityDecision.REVIEW, action.execute(new ImageQualityRouteInput(new ImageQualitySnapshot(80,false,Set.of(ImageQualityReasonCode.BLUR)))).decision()); assertEquals(ImageQualityDecision.REJECT, action.execute(new ImageQualityRouteInput(new ImageQualitySnapshot(0,true,Set.of(ImageQualityReasonCode.INVALID_IMAGE)))).decision()); } }
